<?php
/** Profile preferences preserve multiple follows and exactly one main team. */
use yii\helpers\Html;
$this->title='个人中心';
?>
<section class="page-heading"><h1>个人中心</h1><p>选择一支主队，关注更多球队与球员，定制你的球迷空间。</p></section><div class="tab-bar"><a class="active" href="/profile">我的偏好</a><a href="/profile/notifications">回复通知</a><a href="/forum?feed=main">主队讨论</a><a href="/forum?mine=1">我的主题</a></div>
<form method="post" class="form-panel"><?= csrf_field() ?><input type="hidden" name="replace_preferences" value="1"><?= Html::errorSummary($model,['class'=>'form-errors']) ?><div class="form-grid"><label>我的主队（最多一支）<select data-team-select name="main_team_id"><option value="">暂不选择</option><?php foreach($teams as $t): ?><option data-flag="<?= e(\app\services\TeamUi::url($t)) ?>" value="<?= (int)$t->id ?>" <?= $model->main_team_id==$t->id?'selected':'' ?>><?= e($t->name) ?></option><?php endforeach ?></select></label><label>球迷简介<textarea name="bio" maxlength="500" rows="3"><?= e($model->bio) ?></textarea></label></div>
<details open><summary>关注球队</summary><div class="choice-grid"><?php foreach($teams as $t): ?><label class="choice"><input type="checkbox" name="teams[]" value="<?= (int)$t->id ?>" <?= in_array($t->id,$favoriteTeams)?'checked':'' ?>><?= \app\services\TeamUi::label($t) ?></label><?php endforeach ?></div></details>
<details><summary>关注球员</summary><div class="choice-grid"><?php foreach($players as $p): ?><label class="choice"><input type="checkbox" name="players[]" value="<?= (int)$p->id ?>" <?= in_array($p->id,$favoritePlayers)?'checked':'' ?>><?= \app\services\TeamUi::flag($p->team) ?> <?= e($p->name) ?></label><?php endforeach ?></div></details>
<details><summary>不关注的球队</summary><div class="choice-grid"><?php foreach($teams as $t): ?><label class="choice"><input type="checkbox" name="blocked_teams[]" value="<?= (int)$t->id ?>" <?= in_array($t->id,$blockedTeams)?'checked':'' ?>><?= \app\services\TeamUi::label($t) ?></label><?php endforeach ?></div></details>
<fieldset><legend>内容订阅偏好</legend><div class="choice-grid"><?php foreach(['match'=>'比赛内容','tactics'=>'战术分析','team'=>'球队动态','fanmade'=>'球迷创作','entertainment'=>'场外内容'] as $key=>$label): ?><label class="choice"><input type="checkbox" name="push_<?= e($key) ?>" value="1" <?= !$prefs||$prefs->{'push_'.$key}?'checked':'' ?>><?= e($label) ?></label><?php endforeach ?></div></fieldset><button class="button">保存个人中心 ↗</button></form>
<section class="section"><h2>我的收藏</h2><?php foreach($bookmarks as $t): ?><a class="bookmark-item" href="/forum/<?= (int)$t->id ?>"><?= e($t->title) ?> ↗</a><?php endforeach ?><?php if(!$bookmarks): ?><div class="empty">还没有收藏，在讨论页点击“收藏”即可保存。</div><?php endif ?></section>
